            ["Abyssal Rift rifts from key tier %s: %s%% per finisher's chest, +%s%% per tier above, at most %s%%."] = "Rifts Abyssal Rift a partir do tier de chave %s: %s%% por baú de finalizador, +%s%% por tier acima, no máximo %s%%.",
            ["Adds one modifier to a Rift Key (three at most)."] = "Adiciona um modificador a uma Rift Key (três no máximo).",
            ["Adds one random modifier on an open prefix or suffix of an item with a rarity."] = "Adiciona um modificador aleatório em um prefixo ou sufixo livre de um item com raridade.",
            ["Adds to the emerald gems' movement speed (the gems hold their own %s%% cap)."] = "Soma à velocidade de movimento das gemas esmeralda (as gemas têm o seu próprio limite de %s%%).",
