            ["The world"] = "O mundo",
            ["Thief line"] = "Linha Thief",
            ["Thief line, mastery effect Echoing Flurry: Blade Flurry."] = "Linha Thief, efeito de maestria Echoing Flurry: Blade Flurry.",
            ["Thief line, mastery effect Twin Toss: Shuriken Toss."] = "Linha Thief, efeito de maestria Twin Toss: Shuriken Toss.",
            ["Thief line, mastery effect Wide Smoke: Smoke Bomb."] = "Linha Thief, efeito de maestria Wide Smoke: Smoke Bomb.",
            ["Thief lines"] = "Linhas Thief",
            ["Thorns +%s"] = "Thorns +%s",
            ["Three gems of one type and tier make one of the next tier (Chipped > Flawed > Polished > Flawless > Perfect)."] = "Três gems de um tipo e tier formam uma do tier seguinte (Chipped > Flawed > Polished > Flawless > Perfect).",
            ["Three runes of one support and level make one of the next level (Common > Rare > Epic > Legendary > Mythic)."] = "Três runas de um support e nível formam uma do nível seguinte (Common > Rare > Epic > Legendary > Mythic).",
