            ["Value: the chance on a ranged hit."] = "Valor: a chance num golpe à distância.",
            ["Value: the health left, percent of your maximum."] = "Valor: a vida que sobra, em porcentagem do seu máximo.",
            ["Veiled slot on Rare gear %s%%, Legendary and better %s%%; the orb from kills %s%% (x%s from bosses)."] = "Slot velado em equipamento Rare %s%%, Legendary e melhor %s%%; o orbe dos abates %s%% (x%s dos chefes).",
            ["Veiled tiers"] = "Tiers velados",
            ["Vharok the Blood Colossus: a corpse drop, and every eligible player has %s%% (+ share x %s%%) to get a boss-only unique of that boss."] = "Vharok the Blood Colossus: um drop no corpo, e cada jogador elegível tem %s%% (+ parte x %s%%) de conseguir um unique exclusivo desse chefe.",
